SET NOCOUNT ON;
SET XACT_ABORT ON;
-- Kullanici karari (2026-11-19): Jamadar (sol el silahlari, Kind 140) ve Kurian/Portu veritabanindan tamamen silinir; oyun/sunucu KODU olduğu gibi kalir.
-- Silinenler: Jamadar esyalari (+ Kurian/Portu esyalari), Kurian/Portu sinif skill'leri (MAGIC + MAGIC_TYPE1..9), sinif tanimlari (CREATE_NEW_CHAR_SET/VALUE, CHARACTER_VALIDS, COEFFICIENT),
-- Portu/Kurian NPC ve mob tanimlari ve bu esyalara bagli takas/yukseltme/ITEM_OP kayitlari; mağaza slotlari bosaltilir.
-- Yedek: her tablonun silinen satirlari JK_YEDEK_<tablo> tablosunda, esyalar ITEM_SILINEN_YEDEK'te; tam yedek: LILITH_MYKO_jamadar_kurian_oncesi_2026-11-19.bak.
BEGIN TRAN;
IF EXISTS (SELECT 1 FROM CURRENTUSER) BEGIN THROW 50001, 'Cevrimici oyuncu var, islem iptal', 1; END

-- Kumeler
SELECT DISTINCT Num INTO #n FROM ITEM WHERE Num IS NOT NULL AND (Kind = 140 OR strName LIKE '%Jamadar%' OR strName LIKE '%Kurian%' OR (strName LIKE '%Portu%' AND strName NOT LIKE '%Portugal%') OR Class IN (13, 14, 15));
SELECT MagicNum INTO #m FROM MAGIC WHERE Skill BETWEEN 1130 AND 1159 OR Skill BETWEEN 2130 AND 2159;
SELECT sSid INTO #np FROM K_NPC WHERE strName LIKE '%Kurian%' OR strName LIKE '%Jamadar%' OR strName LIKE '%Portu%';
SELECT sSid INTO #mb FROM K_MONSTER WHERE strName LIKE '%Kurian%' OR strName LIKE '%Jamadar%' OR strName LIKE '%Portu%';

-- Yedekler
IF OBJECT_ID('ITEM_SILINEN_YEDEK') IS NULL SELECT * INTO ITEM_SILINEN_YEDEK FROM ITEM WHERE 1 = 0;
INSERT INTO ITEM_SILINEN_YEDEK SELECT i.* FROM ITEM i WHERE i.Num IN (SELECT Num FROM #n) AND NOT EXISTS (SELECT 1 FROM ITEM_SILINEN_YEDEK y WHERE y.Num = i.Num AND ISNULL(y.strName, '') = ISNULL(i.strName, ''));
IF OBJECT_ID('JK_YEDEK_MAGIC') IS NULL SELECT * INTO JK_YEDEK_MAGIC FROM MAGIC WHERE MagicNum IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_MAGIC_TYPE1') IS NULL SELECT * INTO JK_YEDEK_MAGIC_TYPE1 FROM MAGIC_TYPE1 WHERE iNum IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_MAGIC_TYPE2') IS NULL SELECT * INTO JK_YEDEK_MAGIC_TYPE2 FROM MAGIC_TYPE2 WHERE iNum IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_MAGIC_TYPE3') IS NULL SELECT * INTO JK_YEDEK_MAGIC_TYPE3 FROM MAGIC_TYPE3 WHERE iNum IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_MAGIC_TYPE4') IS NULL SELECT * INTO JK_YEDEK_MAGIC_TYPE4 FROM MAGIC_TYPE4 WHERE iNum IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_MAGIC_TYPE5') IS NULL SELECT * INTO JK_YEDEK_MAGIC_TYPE5 FROM MAGIC_TYPE5 WHERE iNum IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_MAGIC_TYPE6') IS NULL SELECT * INTO JK_YEDEK_MAGIC_TYPE6 FROM MAGIC_TYPE6 WHERE iNum IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_MAGIC_TYPE7') IS NULL SELECT * INTO JK_YEDEK_MAGIC_TYPE7 FROM MAGIC_TYPE7 WHERE nIndex IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_MAGIC_TYPE8') IS NULL SELECT * INTO JK_YEDEK_MAGIC_TYPE8 FROM MAGIC_TYPE8 WHERE iNum IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_MAGIC_TYPE9') IS NULL SELECT * INTO JK_YEDEK_MAGIC_TYPE9 FROM MAGIC_TYPE9 WHERE iNum IN (SELECT MagicNum FROM #m);
IF OBJECT_ID('JK_YEDEK_CREATE_NEW_CHAR_SET') IS NULL SELECT * INTO JK_YEDEK_CREATE_NEW_CHAR_SET FROM CREATE_NEW_CHAR_SET WHERE ClassType IN (13, 14, 15);
IF OBJECT_ID('JK_YEDEK_CREATE_NEW_CHAR_VALUE') IS NULL SELECT * INTO JK_YEDEK_CREATE_NEW_CHAR_VALUE FROM CREATE_NEW_CHAR_VALUE WHERE ClassType IN (13, 14, 15);
IF OBJECT_ID('JK_YEDEK_CHARACTER_VALIDS') IS NULL SELECT * INTO JK_YEDEK_CHARACTER_VALIDS FROM CHARACTER_VALIDS WHERE ClassValue IN (113, 114, 115, 213, 214, 215);
IF OBJECT_ID('JK_YEDEK_COEFFICIENT') IS NULL SELECT * INTO JK_YEDEK_COEFFICIENT FROM COEFFICIENT WHERE sClass IN (113, 114, 115, 213, 214, 215);
IF OBJECT_ID('JK_YEDEK_K_NPC') IS NULL SELECT * INTO JK_YEDEK_K_NPC FROM K_NPC WHERE sSid IN (SELECT sSid FROM #np);
IF OBJECT_ID('JK_YEDEK_K_MONSTER') IS NULL SELECT * INTO JK_YEDEK_K_MONSTER FROM K_MONSTER WHERE sSid IN (SELECT sSid FROM #mb);
IF OBJECT_ID('JK_YEDEK_ITEM_EXCHANGE') IS NULL SELECT * INTO JK_YEDEK_ITEM_EXCHANGE FROM ITEM_EXCHANGE
  WHERE nOriginItemNum1 IN (SELECT Num FROM #n) OR nOriginItemNum2 IN (SELECT Num FROM #n) OR nOriginItemNum3 IN (SELECT Num FROM #n) OR nOriginItemNum4 IN (SELECT Num FROM #n) OR nOriginItemNum5 IN (SELECT Num FROM #n)
     OR nExchangeItemNum1 IN (SELECT Num FROM #n) OR nExchangeItemNum2 IN (SELECT Num FROM #n) OR nExchangeItemNum3 IN (SELECT Num FROM #n) OR nExchangeItemNum4 IN (SELECT Num FROM #n) OR nExchangeItemNum5 IN (SELECT Num FROM #n);
IF OBJECT_ID('JK_YEDEK_ITEM_OP') IS NULL SELECT * INTO JK_YEDEK_ITEM_OP FROM ITEM_OP WHERE nItemID IN (SELECT Num FROM #n);
IF OBJECT_ID('JK_YEDEK_NEW_UPGRADE') IS NULL SELECT * INTO JK_YEDEK_NEW_UPGRADE FROM NEW_UPGRADE WHERE nOriginNumber IN (SELECT Num FROM #n) OR nNewNumber IN (SELECT Num FROM #n);

-- Silme: once baglanti kayitlari, sonra esyalar
DELETE FROM NEW_UPGRADE WHERE nOriginNumber IN (SELECT Num FROM #n) OR nNewNumber IN (SELECT Num FROM #n);
DELETE FROM ITEM_OP WHERE nItemID IN (SELECT Num FROM #n);
DELETE FROM ITEM_EXCHANGE WHERE nIndex IN (SELECT nIndex FROM JK_YEDEK_ITEM_EXCHANGE);
UPDATE ITEM_SELLTABLE SET Item1 = 0 WHERE Item1 IN (SELECT Num FROM #n);   UPDATE ITEM_SELLTABLE SET Item2 = 0 WHERE Item2 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item3 = 0 WHERE Item3 IN (SELECT Num FROM #n);   UPDATE ITEM_SELLTABLE SET Item4 = 0 WHERE Item4 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item5 = 0 WHERE Item5 IN (SELECT Num FROM #n);   UPDATE ITEM_SELLTABLE SET Item6 = 0 WHERE Item6 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item7 = 0 WHERE Item7 IN (SELECT Num FROM #n);   UPDATE ITEM_SELLTABLE SET Item8 = 0 WHERE Item8 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item9 = 0 WHERE Item9 IN (SELECT Num FROM #n);   UPDATE ITEM_SELLTABLE SET Item10 = 0 WHERE Item10 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item11 = 0 WHERE Item11 IN (SELECT Num FROM #n); UPDATE ITEM_SELLTABLE SET Item12 = 0 WHERE Item12 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item13 = 0 WHERE Item13 IN (SELECT Num FROM #n); UPDATE ITEM_SELLTABLE SET Item14 = 0 WHERE Item14 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item15 = 0 WHERE Item15 IN (SELECT Num FROM #n); UPDATE ITEM_SELLTABLE SET Item16 = 0 WHERE Item16 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item17 = 0 WHERE Item17 IN (SELECT Num FROM #n); UPDATE ITEM_SELLTABLE SET Item18 = 0 WHERE Item18 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item19 = 0 WHERE Item19 IN (SELECT Num FROM #n); UPDATE ITEM_SELLTABLE SET Item20 = 0 WHERE Item20 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item21 = 0 WHERE Item21 IN (SELECT Num FROM #n); UPDATE ITEM_SELLTABLE SET Item22 = 0 WHERE Item22 IN (SELECT Num FROM #n);
UPDATE ITEM_SELLTABLE SET Item23 = 0 WHERE Item23 IN (SELECT Num FROM #n); UPDATE ITEM_SELLTABLE SET Item24 = 0 WHERE Item24 IN (SELECT Num FROM #n);
DELETE FROM ITEM WHERE Num IN (SELECT Num FROM #n);

DELETE FROM MAGIC_TYPE1 WHERE iNum IN (SELECT MagicNum FROM #m); DELETE FROM MAGIC_TYPE2 WHERE iNum IN (SELECT MagicNum FROM #m);
DELETE FROM MAGIC_TYPE3 WHERE iNum IN (SELECT MagicNum FROM #m); DELETE FROM MAGIC_TYPE4 WHERE iNum IN (SELECT MagicNum FROM #m);
DELETE FROM MAGIC_TYPE5 WHERE iNum IN (SELECT MagicNum FROM #m); DELETE FROM MAGIC_TYPE6 WHERE iNum IN (SELECT MagicNum FROM #m);
DELETE FROM MAGIC_TYPE7 WHERE nIndex IN (SELECT MagicNum FROM #m); DELETE FROM MAGIC_TYPE8 WHERE iNum IN (SELECT MagicNum FROM #m);
DELETE FROM MAGIC_TYPE9 WHERE iNum IN (SELECT MagicNum FROM #m);
DELETE FROM MAGIC WHERE MagicNum IN (SELECT MagicNum FROM #m);

DELETE FROM CREATE_NEW_CHAR_SET WHERE ClassType IN (13, 14, 15);
DELETE FROM CREATE_NEW_CHAR_VALUE WHERE ClassType IN (13, 14, 15);
DELETE FROM CHARACTER_VALIDS WHERE ClassValue IN (113, 114, 115, 213, 214, 215);
DELETE FROM COEFFICIENT WHERE sClass IN (113, 114, 115, 213, 214, 215);

-- NPC/mob tanimlari ve yalniz onlara ait ganimet tablolari
DELETE FROM K_NPC_ITEM WHERE sIndex IN (SELECT sItem FROM K_NPC WHERE sSid IN (SELECT sSid FROM #np) AND sItem > 0) AND sIndex NOT IN (SELECT sItem FROM K_NPC WHERE sSid NOT IN (SELECT sSid FROM #np) AND sItem > 0);
DELETE FROM K_MONSTER_ITEM WHERE sIndex IN (SELECT sItem FROM K_MONSTER WHERE sSid IN (SELECT sSid FROM #mb) AND sItem > 0) AND sIndex NOT IN (SELECT sItem FROM K_MONSTER WHERE sSid NOT IN (SELECT sSid FROM #mb) AND sItem > 0);
DELETE FROM K_NPC WHERE sSid IN (SELECT sSid FROM #np);
DELETE FROM K_MONSTER WHERE sSid IN (SELECT sSid FROM #mb);
COMMIT TRAN;
